import java.sql.*;
import java.util.*;
import java.util.concurrent.*;

/** Two separately committed transfer steps in one H2 file. No distributed DB, Redis or network. */
public final class BucketEscrow {
    private final String url;
    public record Move(String id,int from,int to,long qty) {}
    public BucketEscrow(String url)throws SQLException {
        this.url=url;
        try(Connection c=open();Statement s=c.createStatement()){
            s.execute("CREATE TABLE IF NOT EXISTS buckets(id INT PRIMARY KEY,available BIGINT NOT NULL CHECK(available>=0),epoch BIGINT NOT NULL)");
            s.execute("CREATE TABLE IF NOT EXISTS holds(rid VARCHAR PRIMARY KEY,bucket INT,qty BIGINT CHECK(qty>0))");
            s.execute("CREATE TABLE IF NOT EXISTS moves(mid VARCHAR PRIMARY KEY,src INT,dst INT,qty BIGINT CHECK(qty>0),state VARCHAR)");
            s.execute("CREATE TABLE IF NOT EXISTS receipts(mid VARCHAR PRIMARY KEY,dst INT,qty BIGINT CHECK(qty>0))");
        }
    }
    private Connection open()throws SQLException{return DriverManager.getConnection(url);}
    public void create(int id,long qty)throws SQLException{
        if(qty<0)throw new IllegalArgumentException();
        try(Connection c=open();PreparedStatement p=c.prepareStatement("INSERT INTO buckets VALUES(?,?,1)")){p.setInt(1,id);p.setLong(2,qty);p.executeUpdate();}
    }
    private long lock(Connection c,int id,long epoch)throws SQLException{
        try(PreparedStatement p=c.prepareStatement("SELECT available,epoch FROM buckets WHERE id=? FOR UPDATE")){
            p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(!r.next()||r.getLong(2)!=epoch)throw new IllegalStateException("missing bucket/stale epoch");return r.getLong(1);}}
    }
    private void set(Connection c,int id,long qty)throws SQLException{
        try(PreparedStatement p=c.prepareStatement("UPDATE buckets SET available=? WHERE id=?")){p.setLong(1,qty);p.setInt(2,id);if(p.executeUpdate()!=1)throw new SQLException("missing bucket");}
    }
    public void nextEpoch(int id)throws SQLException{
        try(Connection c=open();PreparedStatement p=c.prepareStatement("UPDATE buckets SET epoch=epoch+1 WHERE id=? AND epoch<9223372036854775807")){p.setInt(1,id);if(p.executeUpdate()!=1)throw new IllegalArgumentException();}
    }
    public boolean reserve(String rid,int bucket,long epoch,long qty)throws SQLException{
        if(rid==null||rid.isBlank()||qty<=0)throw new IllegalArgumentException();
        try(Connection c=open()){
            c.setAutoCommit(false);
            try{
                long available=lock(c,bucket,epoch);
                try(PreparedStatement p=c.prepareStatement("SELECT bucket,qty FROM holds WHERE rid=?")){
                    p.setString(1,rid);try(ResultSet r=p.executeQuery()){if(r.next()){
                        if(r.getInt(1)!=bucket||r.getLong(2)!=qty)throw new IllegalArgumentException("reservation conflict");c.commit();return true;}}}
                if(available<qty){c.rollback();return false;}
                set(c,bucket,available-qty);
                try(PreparedStatement p=c.prepareStatement("INSERT INTO holds VALUES(?,?,?)")){p.setString(1,rid);p.setInt(2,bucket);p.setLong(3,qty);p.executeUpdate();}
                c.commit();return true;
            }catch(SQLException|RuntimeException e){rollbackPreserving(c, e); throw e;}
        }
    }
    public boolean freeze(Move m,long epoch,boolean fail)throws SQLException {
        if(m.id()==null||m.id().isBlank()||m.qty()<=0||m.from()==m.to())throw new IllegalArgumentException();
        try(Connection c=open()){
            c.setAutoCommit(false);
            try{
                long available=lock(c,m.from(),epoch);
                try(PreparedStatement p=c.prepareStatement("SELECT 1 FROM buckets WHERE id=?")){
                    p.setInt(1,m.to());try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("unknown destination bucket");}}
                try(PreparedStatement p=c.prepareStatement("SELECT src,dst,qty FROM moves WHERE mid=?")){
                    p.setString(1,m.id());try(ResultSet r=p.executeQuery()){if(r.next()){
                        if(r.getInt(1)!=m.from()||r.getInt(2)!=m.to()||r.getLong(3)!=m.qty())throw new IllegalArgumentException("move conflict");c.commit();return true;}}}
                if(available<m.qty()){c.rollback();return false;}
                set(c,m.from(),available-m.qty());
                try(PreparedStatement p=c.prepareStatement("INSERT INTO moves VALUES(?,?,?,?,'FROZEN')")){
                    p.setString(1,m.id());p.setInt(2,m.from());p.setInt(3,m.to());p.setLong(4,m.qty());p.executeUpdate();}
                if(fail)throw new SQLException("injected freeze rollback");
                c.commit();return true;
            }catch(SQLException|RuntimeException e){rollbackPreserving(c, e); throw e;}
        }
    }
    public void receive(Move m,long destinationEpoch,boolean fail)throws SQLException {
        try(Connection c=open()){
            c.setAutoCommit(false);
            try{
                long available=lock(c,m.to(),destinationEpoch);
                // A real cross-shard receiver validates an authenticated durable source certificate.
                try(PreparedStatement p=c.prepareStatement("SELECT src,dst,qty FROM moves WHERE mid=?")){
                    p.setString(1,m.id());try(ResultSet r=p.executeQuery()){
                        if(!r.next()||r.getInt(1)!=m.from()||r.getInt(2)!=m.to()||r.getLong(3)!=m.qty())throw new IllegalArgumentException("no matching frozen transfer");}}
                try(PreparedStatement p=c.prepareStatement("SELECT dst,qty FROM receipts WHERE mid=?")){
                    p.setString(1,m.id());try(ResultSet r=p.executeQuery()){if(r.next()){
                        if(r.getInt(1)!=m.to()||r.getLong(2)!=m.qty())throw new IllegalArgumentException("receipt conflict");c.commit();return;}}}
                set(c,m.to(),Math.addExact(available,m.qty()));
                try(PreparedStatement p=c.prepareStatement("INSERT INTO receipts VALUES(?,?,?)")){p.setString(1,m.id());p.setInt(2,m.to());p.setLong(3,m.qty());p.executeUpdate();}
                if(fail)throw new SQLException("injected receive rollback");
                c.commit();
            }catch(SQLException|RuntimeException e){rollbackPreserving(c, e); throw e;}
        }
    }
    public void acknowledge(String id)throws SQLException{
        // This method models a validated destination receipt; never a timeout-based source refund.
        try(Connection c=open();PreparedStatement p=c.prepareStatement("UPDATE moves SET state='DELIVERED' WHERE mid=? AND EXISTS(SELECT 1 FROM receipts WHERE receipts.mid=moves.mid)")){
            p.setString(1,id);if(p.executeUpdate()!=1)throw new IllegalStateException("receipt not found");}
    }
    public long scalar(String sql)throws SQLException{
        try(Connection c=open();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){r.next();return r.getLong(1);}
    }
    public long total()throws SQLException {
        // Quiescent audit: separate reads are not a common concurrent snapshot.
        long available=scalar("SELECT COALESCE(SUM(available),0) FROM buckets");
        long reserved=scalar("SELECT COALESCE(SUM(qty),0) FROM holds");
        long transit=scalar("SELECT COALESCE(SUM(qty),0) FROM moves m WHERE NOT EXISTS(SELECT 1 FROM receipts r WHERE r.mid=m.mid)");
        return Math.addExact(Math.addExact(available,reserved),transit);
    }
    private static void check(boolean b){if(!b)throw new AssertionError();}
    public static void main(String[] args)throws Exception{
        BucketEscrow s=new BucketEscrow("jdbc:h2:"+args[0]+";LOCK_TIMEOUT=20000");s.create(0,100);s.create(1,0);
        Move m=new Move("m",0,1,40);check(s.freeze(m,1,false));check(s.total()==100);
        s=new BucketEscrow(s.url);check(s.total()==100);final BucketEscrow store=s;
        try{s.receive(m,1,true);throw new AssertionError();}catch(SQLException e){check(e.getMessage().contains("injected"));}
        check(s.scalar("SELECT available FROM buckets WHERE id=1")==0&&s.scalar("SELECT COUNT(*) FROM receipts")==0);
        s.receive(m,1,false);check(s.total()==100&&s.scalar("SELECT COUNT(*) FROM moves WHERE state='FROZEN'")==1);
        // Destination committed, source still FROZEN: replay must not create another 40.
        ExecutorService pool=Executors.newFixedThreadPool(12);
        try{
            List<Callable<Boolean>> jobs=new ArrayList<>();
            for(int i=0;i<30;i++)jobs.add(()->{store.receive(m,1,false);return true;});
            for(Future<Boolean> f:pool.invokeAll(jobs))check(f.get());
            check(s.scalar("SELECT available FROM buckets WHERE id=1")==40);s.acknowledge("m");
            jobs.clear();for(int i=0;i<100;i++){String rid="r"+i;jobs.add(()->store.reserve(rid,0,1,1));}
            int accepted=0;for(Future<Boolean> f:pool.invokeAll(jobs))if(f.get())accepted++;
            check(accepted==60&&s.total()==100&&s.scalar("SELECT available FROM buckets WHERE id=0")==0);
            jobs.clear();for(int i=0;i<30;i++)jobs.add(()->store.reserve("same",1,1,3));
            for(Future<Boolean> f:pool.invokeAll(jobs))check(f.get());
            check(s.scalar("SELECT available FROM buckets WHERE id=1")==37&&s.total()==100);
        }finally{pool.shutdownNow();}
        try{s.freeze(new Move("m",0,1,41),1,false);throw new AssertionError();}catch(IllegalArgumentException ok){}
        try{s.freeze(new Move("rollback",1,0,5),1,true);throw new AssertionError();}catch(SQLException e){check(e.getMessage().contains("injected"));}
        check(s.total()==100&&s.scalar("SELECT COUNT(*) FROM moves WHERE mid='rollback'")==0);
        s.nextEpoch(1);try{s.reserve("stale",1,1,1);throw new AssertionError();}catch(IllegalStateException ok){}
        try{s.freeze(new Move("unknown",1,99,1),2,false);throw new AssertionError();}catch(IllegalArgumentException ok){}
        try{s.freeze(new Move("zero",1,0,0),2,false);throw new AssertionError();}catch(IllegalArgumentException ok){}
        try{s.reserve("negative",1,2,-1);throw new AssertionError();}catch(IllegalArgumentException ok){}
        Move back=new Move("back",1,0,7);check(s.freeze(back,2,false));s.receive(back,1,false);s.acknowledge("back");
        check(new BucketEscrow(s.url).total()==100);
        System.out.println("PASS BucketEscrow: conservation across freeze/reopen/receive/lost-ack, atomic rollback, 30 duplicate credits once, 100 reservations admit60, 30 same reservations once, payload conflict, epoch fencing, invalid destination/quantity, reverse transfer; single H2 only");
    }

    // Keep the primary operation failure; rollback is best-effort diagnostic cleanup.
    static boolean rollbackPreserving(Connection connection, Throwable primary) {
        try {
            connection.rollback();
            return true;
        } catch (Throwable rollbackFailure) {
            if (rollbackFailure != primary) primary.addSuppressed(rollbackFailure);
            return false;
        }
    }
}
